#include "libdm/libdevmapper.h"

/* Mirror of the argv-building loop in target _pool_callback().
 * BEFORE = unconditional store (vulnerable reference-parent form).
 * AFTER  = CU-001 guarded store (fixed form).
 * Uses the real struct dm_config_value / dm_config_value_type_t from the
 * target libdm header. */
static int collect_before(const struct dm_config_value *first, const char **argv)
{
    const struct dm_config_value *cv;
    int args = 0;
    for (cv = first; cv && args < 16; cv = cv->next) {
        if (cv->type != DM_CFG_STRING)
            return -1;
        argv[++args] = cv->v.str;
    }
    if (args == 16)
        return -2;
    return args;
}

static int collect_after(const struct dm_config_value *first, const char **argv)
{
    const struct dm_config_value *cv;
    int args = 0;
    for (cv = first; cv && args < 16; cv = cv->next) {
        if (cv->type != DM_CFG_STRING)
            return -1;
        if (cv->v.str[0])
            argv[++args] = cv->v.str;
    }
    if (args == 16)
        return -2;
    return args;
}

